function safeNext(req, res, next) {
  const sp = new URL(req.originalUrl, 'http://localhost').searchParams;
  for (const k of sp.keys()) if (k !== 'next') return res.sendStatus(400);
  const all = sp.getAll('next');
  if (all.length !== 1 || !all[0].startsWith('/') || all[0].startsWith('//') || all[0].includes('\\')) {
    return res.sendStatus(400);
  }
  next();
}

