const axios = require('axios');
const app = express();

app.get('/preview', async (req, res) => {
  const url = req.query.url;
  if (!url.startsWith('http')) return res.status(400).send('URL 아님');
  const { data } = await axios.get(url);
  res.send(String(data).slice(0, 200));
});

app.listen(3000);

const express = require('express');
const { exec } = require('child_process');
const app = express();

app.get('/ping', (req, res) => {
  const host = req.query.host;
  if (typeof host !== 'string') return res.sendStatus(400);
  exec(`ping -c 1 ${host}`, (e, out) => res.type('text/plain').send(out || ''));
});

app.listen(3000);

const express = require('express');
const app = express();

app.get('/back', (req, res) => {
  const next = req.query.next || '/';
  if (next.length > 200) return res.sendStatus(414);
  res.redirect(next);
});

app.listen(3000);

const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();

app.get('/read', (req, res) => {
  const name = req.query.name.replace('../', '');
  fs.readFile(path.join(__dirname, 'docs', name), 'utf8', (e, t) => res.type('text/plain').send(t || ''));
});

app.listen(3000);
